import java.util.*;

class Solution {
    public List<List<Integer>> combinationSum(int[] candidates, int target) {
        List<List<Integer>> answer = new ArrayList<>();
        Arrays.sort(candidates);
        dfs(candidates, target, 0, new ArrayList<>(), answer);
        return answer;
    }

    private void dfs(int[] candidates, int remaining, int index, List<Integer> path, List<List<Integer>> answer) {
        if (remaining == 0) {
            answer.add(new ArrayList<>(path));
            return;
        }
        if (remaining < 0 || index == candidates.length) {
            return;
        }
        path.add(candidates[index]);
        dfs(candidates, remaining - candidates[index], index, path, answer);
        path.remove(path.size() - 1);
        dfs(candidates, remaining, index + 1, path, answer);
    }
}

